<script setup>
import {ref,onMounted,computed} from 'vue'
import Icon from '../Icon.vue'
import Wallet from '../commerce/Wallet.vue'
import SoulSettings from '../SoulSettings.vue'
import OnboardingSettings from './OnboardingSettings.vue'
import {request} from './client'
const props=defineProps({session:Object})
const tab=ref('Overview'),summary=ref({}),assignments=ref([]),pending=ref([]),error=ref(''),busy=ref(false),note=ref(''),reason=ref(''),workspace=ref('')
const classPrice=ref({classroom:'',amount_minor:0,reason:''})
async function saveClassPrice(){await run(async()=>{await request('owner_pricing','classroom_price',classPrice.value);note.value='Classroom fee assigned. Previously issued invoices are unchanged.'})}
const tabs=['Overview','Pricing','Verification','Payouts','Signup & privacy','Platform guide']
const form=ref({customer:'',customer_kind:'Student',institute:'',product:'Platform',currency:'USD',period:'Monthly',base_minor:0,included_units:0,unit_minor:0,discount_bps:0,tax_bps:0,reason:''})
const estimateUnits=ref(1),grantExpiry=ref(''),grantReason=ref('')
const example=computed(()=>{const f=form.value;const subtotal=Number(f.base_minor)+Math.max(0,Number(estimateUnits.value)-Number(f.included_units))*Number(f.unit_minor);const net=subtotal-Math.floor((subtotal*Number(f.discount_bps)+5000)/10000);return (net+Math.floor((net*Number(f.tax_bps)+5000)/10000))/100})
async function run(fn){busy.value=true;error.value='';note.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function refresh(){[summary.value,assignments.value,pending.value]=await Promise.all([request('portal_session','overview'),request('owner_pricing','assignments'),request('profiles','pending')])}
async function assign(){await run(async()=>{await request('owner_pricing','assign',{data:form.value});await refresh();note.value='A new price revision has been assigned. Previous quotes are unchanged.'})}
async function verify(p,decision){await run(async()=>{await request('profiles','review',{profile:p.name,decision,reason:reason.value,workspace:workspace.value});await refresh();note.value='Verification decision saved.'})}
async function grant(){await run(async()=>{await request('owner_pricing','grant',{customer:form.value.customer,product:form.value.product,expires_at:grantExpiry.value,reason:grantReason.value});note.value='Expiring access granted and recorded in the audit log.'})}
onMounted(()=>run(refresh))
</script>
<template><div class="owner-shell"><aside><a class="entry-brand" href="#">sisu<span>✦</span></a><span class="owner-tag">SUPER ADMIN</span><nav><button v-for="name in tabs" :class="{active:tab===name}" @click="tab=name">{{name}}</button></nav><small>Platform decisions.<br>One calm control room.</small><a href="/api/method/logout">Sign out</a></aside><main><header class="page-heading"><div><span class="eyebrow">YOUR PLATFORM, THOUGHTFULLY MANAGED</span><h1>{{tab==='Overview'?'Room to grow.':tab}}</h1><p>Private owner workspace · {{session.user}}</p></div><button class="button subtle" :disabled="busy" @click="run(refresh)"><Icon name="RefreshCw" :size="16"/>Refresh</button></header><p v-if="error" role="alert" class="error">{{error}}</p><p v-if="note" role="status" class="form-note">{{note}}</p>
<template v-if="tab==='Overview'"><div class="owner-metrics"><article v-for="(value,key) in summary" class="panel"><span>{{key.replaceAll('_',' ')}}</span><strong>{{value}}</strong></article></div><section class="panel owner-block"><span class="eyebrow">CLEAR PRICES. CLEAR PERMISSIONS.</span><h2>Every account has its own agreement.</h2><p>Assign prices for institutes, teachers and students. Customers see their own quote at checkout. No public pricing catalogue, default paid plan or automatic trial.</p><button class="button primary" @click="tab='Pricing'">Manage assigned pricing <Icon name="ArrowRight" :size="16"/></button></section></template>
<template v-else-if="tab==='Pricing'"><form class="panel owner-block owner-form" @submit.prevent="assign"><h2>Assign a price</h2><p>All amounts are in minor units: 100 means 1.00. Percentages use basis points: 100 means 1%. A zero price must be explicitly assigned.</p><div class="owner-fields"><label>Customer email<input v-model="form.customer" type="email" required></label><label>Account type<select v-model="form.customer_kind"><option>Student</option><option>Teacher</option><option>Institute</option></select></label><label v-if="form.customer_kind==='Institute'">Institute record ID<input v-model="form.institute" required></label><label>Product<select v-model="form.product"><option v-for="p in ['Platform','Class payment','AI Papers','Study Space','To-do','Journal']">{{p}}</option></select></label><label>Currency<select v-model="form.currency"><option v-for="c in ['USD','LKR','EUR','GBP','AED','SAR']">{{c}}</option></select></label><label>Billing interval<select v-model="form.period"><option>Monthly</option><option>Yearly</option><option>Per payment</option></select></label><label v-for="(title,key) in {base_minor:'Base amount (minor units)',included_units:'Included active students',unit_minor:'Additional student amount',discount_bps:'Discount (basis points)',tax_bps:'Tax (basis points)'}">{{title}}<input v-model.number="form[key]" type="number" min="0" step="1" :max="key.endsWith('bps')?10000:2000000000" required></label><label>Audit reason<input v-model="form.reason" required maxlength="1000"></label></div><div class="owner-calculator"><label>Calculator: active students / units<input v-model.number="estimateUnits" type="number" min="0" max="10000000"></label><strong>{{form.currency}} {{example.toFixed(2)}}</strong><small>Base + extra units × unit amount − discount + tax. Checkout measures usage on the server.</small></div><button class="button primary" :disabled="busy">Save new price revision</button></form><section class="panel owner-block"><h2>Current assignments</h2><div class="owner-table"><table><thead><tr><th>Customer</th><th>Product</th><th>Currency</th><th>Base</th><th>Interval</th></tr></thead><tbody><tr v-for="a in assignments"><td>{{a.customer}}</td><td>{{a.product}}</td><td>{{a.currency}}</td><td>{{(a.base_minor/100).toFixed(2)}}</td><td>{{a.period}}</td></tr></tbody></table><p v-if="!assignments.length">No prices assigned yet.</p></div></section><form class="panel owner-block" @submit.prevent="saveClassPrice"><h2>Assign a classroom fee</h2><p>Existing classroom checkout uses LKR. Assign the student’s separate Class payment agreement above to set the recurring platform amount.</p><div class="owner-fields"><label>Classroom record ID<input v-model="classPrice.classroom" required></label><label>Class fee · LKR minor units<input v-model.number="classPrice.amount_minor" type="number" min="0" max="2000000000" step="1" required></label><label>Audit reason<input v-model="classPrice.reason" required maxlength="1000"></label></div><button class="button primary" :disabled="busy">Assign classroom fee</button></form><form class="panel owner-block" @submit.prevent="grant"><h2>Grant reviewed premium access</h2><p>Uses the customer and product selected above. This is a recorded access grant, not a payment receipt.</p><div class="owner-fields"><label>Access expires<input v-model="grantExpiry" type="datetime-local" required></label><label>Reason<input v-model="grantReason" required maxlength="1000"></label></div><button class="button subtle" :disabled="busy">Grant until expiry</button></form></template>
<section v-else-if="tab==='Verification'" class="panel owner-block"><h2>Provider verification</h2><label>Institute workspace record ID (required for institutes)<input v-model="workspace" placeholder="The configured IL Institute record on this site"></label><p>Institute approval grants administration of this workspace. Each institute requires its own Frappe site.</p><label>Review reason<textarea v-model="reason" maxlength="1000" placeholder="Record the evidence reviewed and your decision"></textarea></label><article v-for="p in pending" class="owner-review"><div><strong>{{p.display_name}}</strong><p>@{{p.username}} · {{p.kind}} · {{p.country}}</p></div><button class="button primary" :disabled="busy||!reason.trim()" @click="verify(p,'Verified')">Verify & issue code</button><button class="button subtle" :disabled="busy||!reason.trim()" @click="verify(p,'Rejected')">Reject</button></article><p v-if="!pending.length">No profiles awaiting verification.</p></section>
<SoulSettings v-else-if="tab==='Platform guide'"/><OnboardingSettings v-else-if="tab==='Signup & privacy'"/><Wallet v-else-if="tab==='Payouts'" :member="{role:'PlatformAdmin',user:session.user,name:session.user}"/>
</main></div></template>
<style>.owner-shell{min-height:100vh;background:#f7f3fc;color:#44364f;display:grid;grid-template-columns:230px 1fr;--student-card:#fff;--student-ink:#44364f;--student-muted:#80718d;--student-border:#e7dff0;--student-soft:#f4eefb;--student-accent:#9270b8}.owner-shell aside{padding:38px 25px;background:#fffcff;border-right:1px solid #e9dff2;display:flex;flex-direction:column;gap:28px}.owner-tag{font-size:10px;letter-spacing:2px;color:#957cab}.owner-shell nav{display:grid;gap:8px}.owner-shell nav button{padding:15px;text-align:left;background:none;border:0;border-radius:12px;color:#766582;cursor:pointer}.owner-shell nav button.active{background:#efe5fa;color:#745294;font-weight:600}.owner-shell aside small{margin-top:auto;line-height:1.8;color:#8c7a99}.owner-shell aside>a:last-child{font-size:12px;color:#8c6ab0}.owner-shell main{padding:50px;min-width:0;max-width:1500px}.owner-shell h1{margin:12px 0}.owner-shell .page-heading p{font-size:12px}.owner-metrics{display:grid;grid-template-columns:repeat(3,1fr);gap:20px}.owner-metrics article{padding:25px}.owner-metrics span{font-size:12px;text-transform:capitalize;color:#8b7a98}.owner-metrics strong{display:block;font-size:36px;margin-top:15px}.owner-block{padding:30px;margin-top:25px}.owner-block p{font-size:13px;line-height:1.9;margin:15px 0}.owner-fields{display:grid;grid-template-columns:1fr 1fr;gap:20px;margin:25px 0}.owner-block label{display:flex;flex-direction:column;gap:9px;font-size:12px}.owner-block :is(input,select,textarea){padding:13px;border-radius:10px;border:1px solid #e1d5ed;background:#fdfaff;color:#53425f;min-width:0}.owner-calculator{padding:20px;background:#f3ecfa;border-radius:16px;display:flex;gap:25px;align-items:center;margin-bottom:24px;flex-wrap:wrap}.owner-calculator strong{font-size:25px}.owner-calculator small{font-size:11px;flex-basis:100%}.owner-table{overflow:auto}.owner-table table{width:100%;font-size:12px;border-collapse:collapse}.owner-table :is(th,td){padding:15px;text-align:left;border-bottom:1px solid #e9e2f0}.owner-review{display:flex;align-items:center;gap:15px;padding:24px 0;border-bottom:1px solid #ede3f4}.owner-review>div{flex:1}@media(max-width:800px){.owner-shell{display:block}.owner-shell aside{padding:18px}.owner-shell nav{display:flex;overflow:auto}.owner-shell aside small,.owner-tag{display:none}.owner-shell main{padding:24px}.owner-metrics{grid-template-columns:1fr 1fr}.owner-fields{grid-template-columns:1fr}.owner-review{flex-wrap:wrap}}
</style>
